# wl_report.py: writes misc/reviews/nick-runs/checks-WL.md from data/wl_*.json (the Weil ladder runs of code/wl_weil.py). Run locally (reads json only), e.g.
#   timeout 120 python3 -I code/wl_report.py
# If data/wl_grid3.json is absent it reads the live Hopper log of the job wl_grid3 and writes data/wl_grid3_partial.json.
import json, os, glob, math, subprocess
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))) + '/'
D = R + 'data/'
cells = {}


def addr(r, src):
    k = (r['X'], r['N'])
    if r.get('certified_positive') or k not in cells:
        r = dict(r)
        r['src'] = src
        cells[k] = r


for f in ('wl_grid.json', 'wl_grid2.json', 'wl_pcert.json'):
    for r in json.load(open(D + f)):
        addr(r, f)
if os.path.exists(D + 'wl_grid3.json'):
    g3 = 'wl_grid3.json'
    for r in json.load(open(D + 'wl_grid3.json')):
        addr(r, g3)
else:
    out = subprocess.run(['ssh', 'hopper', 'cat /scratch/vsokolov/rh_book_repro/agents/wl_grid3/slurm-*.log'], capture_output=True, text=True).stdout
    rs = [json.loads(l) for l in out.splitlines() if l.startswith('{')]
    json.dump(rs, open(D + 'wl_grid3_partial.json', 'w'), indent=1)
    g3 = 'wl_grid3_partial.json'
    for r in rs:
        addr(r, g3)
grid3_tasks = [tuple(int(v) for v in t.split(':')) for t in open(D + 'wl_grid3_tasks.txt').read().split(',')]
pending = [t for t in grid3_tasks if t not in cells]
ncert = sum(1 for r in cells.values() if r.get('certified_positive'))
fl = {}
for f in ('wl_float.json', 'wl_float2.json'):
    for r in json.load(open(D + f)):
        fl[(r['X'], r['N'])] = r
pil = {}
for f in glob.glob(R + 'misc/reviews/nick-runs/vadim_runs/pilot/*.json'):
    p = json.load(open(f))
    pil[(p['X'], p['N'])] = p
