def lg(s):
    m, e = (s.split('e') + ['0'])[:2]
    return math.log10(float(m)) + int(e)


def fe(s, n=4):
    if 'e' not in s:
        return '%.*e' % (n - 1, float(s))
    m, e = s.split('e')
    return '%.*fe%d' % (n - 1, float(m), int(e))


